export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const match = url.pathname.match(/^\/files\/([^/]+)$/);
    if (!match) {
      return new Response("Not found", { status: 404 });
    }
    const name = decodeURIComponent(match[1]);

    if (request.method === "PUT") {
      return handlePut(request, env, name);
    }
    if (request.method === "GET") {
      return handleGet(request, env, name);
    }
    return new Response("Method not allowed", { status: 405 });
  },
};

async function handlePut(request, env, name) {
  const key = request.headers.get("X-API-Key");
  if (!key || key !== env.API_KEY) {
    return new Response("Unauthorized", { status: 401 });
  }

  const contentType = request.headers.get("Content-Type") || "application/octet-stream";
  const body = await request.arrayBuffer();

  const description = await describeUpload(env, body, contentType, name);

  await env.BUCKET.put(name, body, {
    httpMetadata: { contentType },
    customMetadata: { description },
  });

  return new Response(JSON.stringify({ name, size: body.byteLength, description }), {
    status: 200,
    headers: { "Content-Type": "application/json" },
  });
}

async function handleGet(request, env, name) {
  const object = await env.BUCKET.get(name);
  if (!object) {
    return new Response("Not found", { status: 404 });
  }

  const headers = new Headers();
  object.writeHttpMetadata(headers);
  headers.set("etag", object.httpEtag);
  if (object.customMetadata && object.customMetadata.description) {
    headers.set("X-Description", object.customMetadata.description);
  }

  return new Response(object.body, { headers });
}

async function describeUpload(env, body, contentType, name) {
  try {
    let prompt;
    if (contentType.startsWith("text/") || contentType.includes("json") || contentType.includes("xml")) {
      const text = new TextDecoder().decode(body).slice(0, 4000);
      prompt = `Write exactly one concise sentence describing the following uploaded file named "${name}" (content type ${contentType}):\n\n${text}`;
    } else {
      prompt = `Write exactly one concise sentence describing an uploaded file named "${name}" with content type "${contentType}" and size ${body.byteLength} bytes. Do not make up specific contents; describe it generically based on the type.`;
    }

    const result = await env.AI.run("@cf/meta/llama-3-8b-instruct", {
      messages: [
        { role: "system", content: "You produce exactly one short, factual sentence and nothing else." },
        { role: "user", content: prompt },
      ],
    });

    const raw = (result && (result.response || result.result || "")).toString().trim();
    const firstSentence = raw.split(/(?<=[.!?])\s/)[0] || raw;
    return firstSentence || "An uploaded file.";
  } catch (err) {
    return "An uploaded file (description unavailable).";
  }
}
